def named(rel,q,name,title,desc,roles=('utterer','record-owner')):
 v=zc.verify(rel,q);assert v['ok'],(rel,q)
 return {'RelPath':rel,'FromLb':v['fromLb'],'ToLb':v['toLb'],'Kwic':q,'MasterName':name,'Curated':True,'AttributionNote':f'{title}: {desc}','ContextMasters':[{'MasterName':name,'Roles':list(roles)}],'DraftActorProof':{'ExactHeadwordClause':q,'SpeechFrame':desc,'FullCaseDecision':f'{name} owns the selected headword-bearing statement.'}}
def anon(rel,q,title,respondent,grammar):
 v=zc.verify(rel,q);assert v['ok']
 return {'RelPath':rel,'FromLb':v['fromLb'],'ToLb':v['toLb'],'Kwic':q,'MasterName':None,'Curated':True,'AttributionNote':f'{title}: an unnamed monastic asks the headword question; {respondent} answers separately.','ActorAttribution':{'Status':'reviewed-unnamed','Kind':'monastic questioner','ActorLabel':'an unnamed monastic questioner','ActorRole':'questioner','RungsChecked':['line','expanded-context','section-header','book-title','tei-header','parallel-passage'],'GrammarEvidence':grammar,'ReviewedBy':'Codex fresh f001 lane A evidence-first','ReviewedUtc':'2026-07-15T00:00:00Z'},'ContextMasters':[{'MasterName':respondent,'Roles':['respondent','case-figure']}],'DraftActorProof':{'GrammaticalSubject':'The unnamed monastic asking the headword question.','FullCaseDecision':f'The questioner owns the headword; {respondent} owns the separate answer.'}}
def write(eid,term,sense,work):
 d=ROOT/'fresh-build/entries'/eid;d.mkdir(parents=True,exist_ok=True)
 entry={'Id':eid,'SourceTerm':term,'CorpusBaselineSha256':BASE,'CreatedBy':'Codex fresh f001 lane A evidence-first','WrittenUtc':'2026-07-15T00:00:00Z','Senses':[sense]}
 (d/'evidence.draft.json').write_text(json.dumps({'SchemaVersion':1,'Entry':entry},ensure_ascii=False,indent=2)+'\n')
 (d/'WORK.md').write_text(work)

